type Config struct {
    Capacity int
}

type entry struct {
    key   string
    value string
}

type Cache struct {
    mu       sync.RWMutex
    capacity int
    ll       *list.List
    items    map[string]*list.Element
}

func New(config Config) (*Cache, error) {
    if config.Capacity <= 0 {
        return nil, errors.New("capacity must be positive")
    }
    return &Cache{
        capacity: config.Capacity,
        ll:       list.New(),
        items:    make(map[string]*list.Element),
    }, nil
}

func (c *Cache) Get(key string) (string, bool) {
    c.mu.RLock()
    elem, ok := c.items[key]
    c.mu.RUnlock()
    if !ok {
        return "", false
    }
    c.mu.Lock()
    // Check again in case it was evicted between RUnlock and Lock
    elem, ok = c.items[key]
    if !ok {
        c.mu.Unlock()
        return "", false
    }
    c.ll.MoveToFront(elem)
    v := elem.Value.(*entry).value
    c.mu.Unlock()
    return v, true
}

func (c *Cache) Put(key string, value string) {
    c.mu.Lock()
    defer c.mu.Unlock()
    if elem, ok := c.items[key]; ok {
        c.ll.MoveToFront(elem)
        elem.Value.(*entry).value = value
        return
    }
    if c.ll.Len() >= c.capacity {
        // Evict LRU (back of list)
        back := c.ll.Back()
        if back != nil {
            e := back.Value.(*entry)
            delete(c.items, e.key)
            c.ll.Remove(back)
        }
    }
    e := &entry{key: key, value: value}
    elem := c.ll.PushFront(e)
    c.items[key] = elem
}

func (c *Cache) Len() int {
    c.mu.RLock()
    defer c.mu.RUnlock()
    return c.ll.Len()
}
